import Handlebars from 'handlebars';
import ifCondAnd from '../helper/funcs/ifCondAnd.js';

Handlebars.registerHelper('ifCondAnd', ifCondAnd);

describe('ifCondAnd helper', () => {
  
  it('should return true block for multiple true conditions (== and >)', () => {
    const template = Handlebars.compile('{{#ifCondAnd 5 "==" 5 10 ">" 5}}All True{{^}}One or More False{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('All True');
  });

  it('should return false block if any condition is false', () => {
    const template = Handlebars.compile('{{#ifCondAnd 5 "==" 5 10 "<" 5}}All True{{^}}One or More False{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('One or More False');
  });

  it('should handle strict equality and inequality (=== and !==)', () => {
    const template = Handlebars.compile('{{#ifCondAnd "5" "===" "5" 5 "!==" "6"}}All Strictly Equal{{^}}Not Strictly Equal{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('All Strictly Equal');
  });

  it('should handle "in" operator with multiple values', () => {
    const template = Handlebars.compile('{{#ifCondAnd "softpro.ua" "in" "help.softpro.ua,softpro.ua" "123" "in" "123,456"}}In All{{^}}Not In All{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('In All');
  });

  it('should handle "not in" operator for multiple values', () => {
    const template = Handlebars.compile('{{#ifCondAnd "example" "not in" "softpro.ua,help.ua" "test" "not in" "123,456"}}Not In All{{^}}In All{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('Not In All');
  });

  it('should handle ">" and "<" operators for number comparison', () => {
    const template = Handlebars.compile('{{#ifCondAnd 10 ">" 5 3 "<" 4}}Comparison True{{^}}Comparison False{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('Comparison True');
  });

  it('should handle logical operators && and ||', () => {
    const template = Handlebars.compile('{{#ifCondAnd true "&&" true false "||" true}}All True{{^}}One or More False{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('All True');
  });

  it('should handle array intersection (&)', () => {
    const template = Handlebars.compile('{{#ifCondAnd arr1 "&" arr2}}Intersect{{^}}No Intersect{{/ifCondAnd}}');
    const result = template({ arr1: [1, 2, 3], arr2: [3, 4, 5] });
    expect(result).toBe('Intersect');
  });

  it('should handle no intersection with "&" operator', () => {
    const template = Handlebars.compile('{{#ifCondAnd arr1 "&" arr2}}Intersect{{^}}No Intersect{{/ifCondAnd}}');
    const result = template({ arr1: [1, 2], arr2: [3, 4] });
    expect(result).toBe('No Intersect');
  });

  it('should handle substring inclusion (~) and exclusion (!~)', () => {
    const templateContains = Handlebars.compile('{{#ifCondAnd "softpro" "~" "soft"}}Contains{{^}}Does Not Contain{{/ifCondAnd}}');
    const resultContains = templateContains({});
    expect(resultContains).toBe('Contains');

    const templateDoesNotContain = Handlebars.compile('{{#ifCondAnd "softpro" "!~" "help"}}Does Not Contain{{^}}Contains{{/ifCondAnd}}');
    const resultDoesNotContain = templateDoesNotContain({});
    expect(resultDoesNotContain).toBe('Does Not Contain');
  });

  it('should handle date within period using "period" operator', () => {
    const template = Handlebars.compile('{{#ifCondAnd "2023-01-01" "period" "2025-01-01"}}Within Period{{^}}Out of Period{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('Within Period');
  });

  it('should return false for date outside period using "period" operator', () => {
    const template = Handlebars.compile('{{#ifCondAnd "2019-01-01" "period" "2022-01-01"}}Within Period{{^}}Out of Period{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('Out of Period');
  });

  it('should handle mixed conditions and return true if all are met', () => {
    const template = Handlebars.compile('{{#ifCondAnd 5 "==" 5 "test" "~" "te" "softpro.ua" "in" "softpro.ua,help.ua"}}All Conditions Met{{^}}One or More Conditions Not Met{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('All Conditions Met');
  });

  it('should return false if any condition in mixed operators fails', () => {
    const template = Handlebars.compile('{{#ifCondAnd 5 "==" 5 "test" "!~" "te" "softpro.ua" "in" "softpro.ua,help.ua"}}All Conditions Met{{^}}One or More Conditions Not Met{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('One or More Conditions Not Met');
  });

  it('should handle unsupported operator and render the inverse block', () => {
    const template = Handlebars.compile('{{#ifCondAnd 5 "unknown" 5}}This will not be displayed{{^}}Unsupported Operator{{/ifCondAnd}}');
    const result = template({});
    expect(result).toBe('Unsupported Operator');
  });

  it('should return true block when both conditions are not null', () => {
    const template = Handlebars.compile('{{#ifCondAnd object_id "!=" null dataset_table "!=" null}}Both Not Null{{^}}One or More Null{{/ifCondAnd}}');
    const result = template({ object_id: 123, dataset_table: 'table1' });
    expect(result).toBe('Both Not Null');
  });

  it('should return false block if one of the conditions is null', () => {
    const template = Handlebars.compile('{{#ifCondAnd object_id "!=" null dataset_table "!=" null}}Both Not Null{{^}}One or More Null{{/ifCondAnd}}');
    const result1 = template({ object_id: null, dataset_table: 'table1' });
    const result2 = template({ object_id: 123, dataset_table: null });

    expect(result1).toBe('One or More Null');
    expect(result2).toBe('One or More Null');
  });

  it('should return false block if both conditions are null', () => {
    const template = Handlebars.compile('{{#ifCondAnd object_id "!=" null dataset_table "!=" null}}Both Not Null{{^}}One or More Null{{/ifCondAnd}}');
    const result = template({ object_id: null, dataset_table: null });
    expect(result).toBe('One or More Null');
  });

  it('should return true block for null comparison with equality (== null)', () => {
    const template = Handlebars.compile('{{#ifCondAnd object_id "==" null}}Is Null{{^}}Not Null{{/ifCondAnd}}');
    const result = template({ object_id: null });
    expect(result).toBe('Is Null');
  });

  it('should return false block for non-null value with equality (== null)', () => {
    const template = Handlebars.compile('{{#ifCondAnd object_id "==" null}}Is Null{{^}}Not Null{{/ifCondAnd}}');
    const result = template({ object_id: 123 });
    expect(result).toBe('Not Null');
  });

  it('should return true block when all conditions are true (array intersection and equality)', () => {
    const template = Handlebars.compile('{{#ifCondAnd groupList "&" "3126250868588938939,2256063440420341476,3243057626522584083" userType "==" "admin"}}1{{^}}0{{/ifCondAnd}}');
    const result = template({
      groupList: ['2256063440420341476'],
      userType: 'admin'
    });
    expect(result).toBe('1');
  });

  it('should return false block when at least one condition is false (array intersection and equality)', () => {
    const template = Handlebars.compile('{{#ifCondAnd groupList "&" "3126250868588938939,3243057626522584083" userType "==" "admin"}}1{{^}}0{{/ifCondAnd}}');
    const result = template({
      groupList: ['2256063440420341476'],
      userType: 'admin'
    });
    expect(result).toBe('0');
  });

});
